select amount_bucket, avg_amount, card_amount from (select case when amount >= 1410 then 'high' when amount >= 640 then 'mid' else 'low' end as amount_bucket, round(avg(amount), 2) as avg_amount, sum(case when method = 'card' then amount else 0 end) as card_amount from payments where status = 'REFUNDED' group by case when amount >= 1410 then 'high' when amount >= 640 then 'mid' else 'low' end) as agg where avg_amount < 38 order by card_amount desc
